341	
342	export type ChatAnswer = { answer: string; conversationId: string; toolsUsed?: string[]; followUps?: FollowUp[] };
343	export type ChatStreamEvent =
344	  | { type: "started" }
345	  | { type: "tool"; id?: string; name: string; state: "running" | "done" | "failed"; input?: unknown; output?: string }
346	  | { type: "plan"; steps: string[] }
347	  | { type: "steered"; steers: { id: string; content: string }[] }
348	  | { type: "delta"; text: string }
349	  | ({ type: "answer" } & ChatAnswer)
350	  | { type: "result"; status: number; body: unknown };
351	
352	/** Reads the opt-in NDJSON stream, or a plain JSON response, into the final status and body. */
353	async function readResponse(response: Response, onEvent: (event: ChatStreamEvent) => void): Promise<{ ok: boolean; body: { error?: string } & Partial<ChatAnswer> }> {
354	  if (!response.headers.get("content-type")?.includes("application/x-ndjson") || !response.body) return { ok: response.ok, body: await response.json() };
355	  const reader = response.body.pipeThrough(new TextDecoderStream()).getReader();
356	  let buffer = "";
357	  for (;;) {
358	    const { value, done } = await reader.read();
359	    buffer += value ?? "";
360	    const lines = buffer.split("\n");
361	    buffer = done ? "" : lines.pop()!;
362	    for (const line of lines.filter(Boolean)) {
363	      const event = JSON.parse(line) as ChatStreamEvent;
364	      if (event.type === "result") return { ok: event.status < 400, body: event.body as { error?: string } };
365	      onEvent(event);
366	    }
367	    if (done) throw new Error("The answer stream ended early; reload to see whether it was saved");
368	  }
369	}
