"use client";

import { useEffect, useReducer, useRef, useState } from "react";
import { readResponse, type ChatAnswer } from "./use-chat-request";
import { VoiceCallController, type CallAsk } from "./voice-call-controller";

export type CallStatus = "connecting" | "live" | "ended" | "error";

function failure(cause: unknown) {
  const name = cause instanceof DOMException ? cause.name : "";
  if (name === "NotAllowedError" || name === "SecurityError") return "Microphone access was denied. Allow it in your browser to call Moneo.";
  if (name === "NotFoundError") return "No microphone was found.";
  return cause instanceof Error && cause.message ? cause.message : "Could not connect the call. Check your connection and try again.";
}

/** Average loudness (0-1) of an analyser's current frame. */
function level(analyser: AnalyserNode | null, buffer: Uint8Array<ArrayBuffer>) {
  if (!analyser) return 0;
  analyser.getByteTimeDomainData(buffer);
  let sum = 0;
  for (const value of buffer) sum += ((value - 128) / 128) ** 2;
  return Math.min(1, Math.sqrt(sum / buffer.length) * 4);
}

/**
 * A live GPT-Live call over WebRTC. GPT-Live only talks; every question it hands off runs through /api/chat
 * in this conversation (see VoiceCallController), and the answer is sent back for it to speak.
 */
export function useVoiceCall(conversationId: string, onAnswer?: (question: string, answer: ChatAnswer) => void) {
  const [status, setStatus] = useState<CallStatus>("connecting");
  const [error, setError] = useState("");
  const [muted, setMuted] = useState(false);
  const [, render] = useReducer((count: number) => count + 1, 0);
  const channel = useRef<RTCDataChannel | null>(null);
  const mic = useRef<MediaStream | null>(null);
  const analysers = useRef<{ mic: AnalyserNode | null; moneo: AnalyserNode | null }>({ mic: null, moneo: null });
  const answered = useRef(onAnswer);
  useEffect(() => { answered.current = onAnswer; });
  const aborts = useRef(new Map<string, AbortController>());

  const [controller] = useState(() => {
    const ask: CallAsk = async (payload, onEvent) => {
      const abort = new AbortController();
      aborts.current.set(payload.requestId, abort);
      try {
        const response = await fetch("/api/chat", { method: "POST", signal: abort.signal, headers: { "Content-Type": "application/json", Accept: "application/x-ndjson, application/json" }, body: JSON.stringify(payload) });
        return await readResponse(response, onEvent);
      } finally { aborts.current.delete(payload.requestId); }
    };
    return new VoiceCallController({ conversationId, ask, onChange: render, onAnswer: (question, answer) => answered.current?.(question, answer),
      send: event => { if (channel.current?.readyState === "open") channel.current.send(JSON.stringify(event)); } });
  });

  useEffect(() => {
    let closed = false;
    const pc = typeof RTCPeerConnection === "undefined" ? null : new RTCPeerConnection();
    const audio = new Audio();
    audio.autoplay = true;
    let context: AudioContext | null = null, wakeLock: WakeLockSentinel | null = null;
    const lock = () => { if (document.visibilityState === "visible") navigator.wakeLock?.request("screen").then(sentinel => { if (closed) void sentinel.release(); else wakeLock = sentinel; }, () => {}); };
    async function connect() {
      if (!pc || !navigator.mediaDevices?.getUserMedia) throw new Error("This browser cannot make voice calls. Try a recent Chrome, Safari or Firefox.");
      const stream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true } });
      if (closed) { stream.getTracks().forEach(track => track.stop()); return; }
      mic.current = stream;
      context = new AudioContext();
      const analyser = (source: MediaStream) => { const node = context!.createAnalyser(); node.fftSize = 512; context!.createMediaStreamSource(source).connect(node); return node; };
      analysers.current.mic = analyser(stream);
      pc.addTrack(stream.getAudioTracks()[0], stream);
      pc.ontrack = event => { audio.srcObject = event.streams[0]; analysers.current.moneo = analyser(event.streams[0]); };
      const dc = pc.createDataChannel("oai-events");
      channel.current = dc;
      dc.onmessage = message => {
        const event = JSON.parse(message.data);
        if (event.type === "session.started") { setStatus("live"); lock(); }
        else if (event.type === "session.closed") setStatus("ended");
        controller.handle(event);
      };
      pc.onconnectionstatechange = () => { if (!closed && pc.connectionState === "failed") { setStatus("error"); setError("The call dropped. Check your connection and try again."); } };
      const offer = await pc.createOffer();
      await pc.setLocalDescription(offer);
      const response = await fetch("/api/voice/session", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ sdp: offer.sdp, conversationId }) });
      const body = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(body.error ?? "Could not start the call");
      if (!closed) await pc.setRemoteDescription({ type: "answer", sdp: body.sdp });
    }
    connect().catch(cause => { if (!closed) { setStatus("error"); setError(failure(cause)); } });
    document.addEventListener("visibilitychange", lock);
    return () => {
      closed = true;
      document.removeEventListener("visibilitychange", lock);
      try { if (channel.current?.readyState === "open") channel.current.send(JSON.stringify({ type: "session.close" })); } catch { /* already closed */ }
      channel.current = null;
      mic.current?.getTracks().forEach(track => track.stop());
      pc?.close();
      audio.srcObject = null;
      void context?.close();
      void wakeLock?.release();
      analysers.current = { mic: null, moneo: null };
    };
  }, [controller, conversationId]);

  function toggleMute() {
    const next = !muted;
    mic.current?.getAudioTracks().forEach(track => { track.enabled = !next; });
    setMuted(next);
  }

  async function cancel(requestId: string) {
    controller.cancel(requestId);
    // Cancellation can arrive before the server has claimed the request.
    for (let attempt = 0; attempt < 10; attempt++) {
      const response = await fetch("/api/chat", { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ requestId }) }).catch(() => null);
      if (response?.status !== 404) break;
      await new Promise(resolve => setTimeout(resolve, 100));
    }
    aborts.current.get(requestId)?.abort();
  }

  /** Current loudness of the user's mic and of Moneo's voice, for the orb; read every frame without re-rendering. */
  const [buffer] = useState(() => new Uint8Array(512));
  const levels = () => ({ mic: muted ? 0 : level(analysers.current.mic, buffer), moneo: level(analysers.current.moneo, buffer) });

  return {
    status, error: error || controller.error, muted, toggleMute, cancel, levels,
    captions: controller.captions, tasks: controller.tasks, cards: controller.cards,
    typed: (text: string) => controller.typed(text),
    /** Moneo is answering or working; used for the orb's thinking state. */
    thinking: controller.running.length > 0,
  };
}

"use client";

import { useEffect, useRef, useState } from "react";
import { Loader2, Mic, MicOff, PhoneOff, Send, X } from "lucide-react";
import { IouCard } from "@/components/iou-card";
import { useVoiceCall } from "@/lib/ai/use-voice-call";
import type { ChatAnswer } from "@/lib/ai/use-chat-request";

/** The orb follows whoever is talking; it holds still when reduced motion is asked for. */
function Orb({ levels, state }: { levels: () => { mic: number; moneo: number }; state: "connecting" | "listening" | "thinking" | "speaking" | "idle" }) {
  const orb = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    let frame = 0, smooth = 0;
    const tick = () => {
      const { mic, moneo } = levels();
      smooth += (Math.max(mic, moneo) - smooth) * 0.25;
      orb.current?.style.setProperty("--level", smooth.toFixed(3));
      frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [levels]);
  const tone = state === "speaking" ? "from-lime to-brand" : state === "thinking" ? "from-ai to-ai-border" : "from-ai-border to-lime";
  return <div aria-hidden="true" className="relative grid size-40 place-items-center sm:size-48">
    <div className={`absolute inset-0 rounded-full bg-gradient-to-br ${tone} opacity-25 blur-2xl transition-colors duration-500`} />
    <div ref={orb} style={{ transform: "scale(calc(1 + var(--level, 0) * 0.35))" }}
      className={`size-28 rounded-full bg-gradient-to-br ${tone} shadow-[0_0_60px_-10px] shadow-ai/50 transition-colors duration-500 sm:size-32 ${state === "thinking" || state === "connecting" ? "motion-safe:animate-pulse" : ""}`} />
  </div>;
}

/** A live voice call with Moneo: speak or type, see captions and running tasks, and tap the cards it makes. */
export function VoiceCall({ conversationId, onAnswer, onClose }: { conversationId: string; onAnswer: (question: string, answer: ChatAnswer) => void; onClose: () => void }) {
  const call = useVoiceCall(conversationId, onAnswer);
  const [text, setText] = useState("");
  const captions = useRef<HTMLDivElement>(null);
  useEffect(() => { captions.current?.scrollTo({ top: captions.current.scrollHeight }); }, [call.captions]);
  const last = call.captions.at(-1);
  const state = call.status === "connecting" ? "connecting" : call.status !== "live" ? "idle" : last?.role === "assistant" && !call.thinking ? "speaking" : call.thinking ? "thinking" : "listening";
  const label = { connecting: "Connecting…", listening: call.muted ? "Muted" : "Listening", thinking: "Working on it", speaking: "Moneo is talking", idle: call.status === "ended" ? "Call ended" : "Call failed" }[state];
  const running = call.tasks.filter(task => task.status === "running");
  const round = "grid size-14 place-items-center rounded-full transition-colors focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ai";

  return <section role="dialog" aria-modal="true" aria-label="Voice call with Moneo" className="fixed inset-0 z-50 flex flex-col bg-background lg:absolute">
    <header className="flex items-center justify-between gap-3 border-b border-border px-4 py-3 sm:px-8">
      <p className="font-display text-lg font-semibold">Call with Moneo</p>
      <p role="status" className="flex items-center gap-2 text-sm text-muted-foreground">{state === "connecting" && <Loader2 className="size-4 motion-safe:animate-spin" aria-hidden="true" />}{label}</p>
    </header>
    <div className="mx-auto flex min-h-0 w-full max-w-[820px] flex-1 flex-col gap-4 overflow-y-auto px-4 py-6 sm:px-8">
      <div className="flex flex-col items-center gap-2"><Orb levels={call.levels} state={state} /></div>
      {call.error && <p role="alert" className="rounded-lg border border-danger/40 px-3 py-2 text-sm text-danger">{call.error}</p>}
      <div ref={captions} aria-live="polite" aria-label="Live captions" className="max-h-48 space-y-2 overflow-y-auto text-[15px] leading-relaxed">
        {!call.captions.length && call.status === "live" && <p className="text-center text-muted-foreground">Say hi, ask about your money, or tell Moneo what you spent.</p>}
        {call.captions.slice(-8).map(caption => <p key={caption.id} className={caption.role === "user" ? "ml-auto w-fit max-w-[85%] rounded-2xl bg-muted px-3 py-1.5" : "max-w-[90%]"}>
          <span className="sr-only">{caption.role === "user" ? "You: " : "Moneo: "}</span>{caption.text}</p>)}
      </div>
      {call.tasks.length > 0 && <div>
        <p className="eyebrow pb-1.5">{running.length ? `Working on ${running.length}` : "Done"}</p>
        <ul className="space-y-1.5" aria-label="Tasks">
          {call.tasks.slice(-6).map(task => <li key={task.requestId} className="flex items-center gap-2 rounded-xl border border-border bg-card px-3 py-2 text-sm">
